// 固定数据，模拟一次耗时读取，不涉及真实网络
const records = [
  { id: 1, amount: 4 },
  { id: 2, amount: 6 },
];

// shouldFail 为 true 时走失败路径，否则走成功路径
export function readRecords(options = {}) {
  const shouldFail = options.shouldFail === true;

  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (shouldFail) {
        reject(new Error('记录读取失败'));
        return;
      }
      resolve(records);
    }, 0);
  });
}

import { readRecords } from './data/records.js';

// async 函数：无论里面写 return 什么，调用者拿到的都是 Promise
export async function loadTotal(options) {
  const rows = await readRecords(options);
  const total = rows.reduce((sum, row) => sum + row.amount, 0);
  return total;
}

import { loadTotal } from './loadTotal.js';

function report(label, value) {
  console.log(label, value);
}

async function run() {
  // 只调用、不 await：函数开始执行，但立刻把 Promise 还回来
  const pending = loadTotal();
  report('1. 拿到 Promise 后立刻执行这一行：', pending instanceof Promise);

  try {
    const total = await pending;
    report('2. await 得到兑现值：', total);
  } catch (error) {
    report('2. 失败路径：', error.message);
  }

  try {
    const total = await loadTotal({ shouldFail: true });
    report('3. await 得到兑现值：', total);
  } catch (error) {
    report('3. 失败路径：', error.message);
  }
}

run();
